using System;using System.IO;using System.Linq;using System.Text;
namespace DoomSNESed {
    public static class PortalCompatibilityTests {
        static void Check(bool value,string message){Bin.Require(value,"Portal compatibility: "+message);}
        static void Name(byte[] bytes,int p,string name){Array.Clear(bytes,p,8);byte[] text=Encoding.ASCII.GetBytes(name);Buffer.BlockCopy(text,0,bytes,p,text.Length);}
        public static void Run(string path,string output){string resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"),folder=Path.Combine(output,"portals-020");Directory.CreateDirectory(folder);var rom=new Rom(path,resources);string fixture=Path.Combine(folder,"portals.wad");InteractionTests.Fixture(rom,fixture);
            foreach(int blocking in new[]{0,2,1,3})foreach(bool masked in new[]{false,true}){
                var wad=new WadFile(fixture);var lumps=wad.Map("E1M1");byte[] lines=lumps["LINEDEFS"],sides=lumps["SIDEDEFS"];int p=Enumerable.Range(0,lines.Length/14).First(i=>Bin.U16(lines,i*14+12)!=65535)*14;int front=Bin.U16(lines,p+10)*30,back=Bin.U16(lines,p+12)*30;Bin.W16(lines,p+4,4|32|128|blocking);Bin.W16(lines,p+6,blocking==2?124:0);
                if(masked){Name(sides,front+20,"TESTFENC");Name(sides,back+20,"TESTBACK");}
                var converter=new WadConverter(rom,resources){AllowLossy=false,Options=new ConversionOptions{WeldVertices=false,CollapseWalls=false,CompactTags=false}};var map=converter.Import(wad,"E1M1",0,false);var line=map.Walls[p/14];Check(((line.Flags&8)!=0)==((blocking&1)!=0),"only explicit player blocking produces native impassable");Check((line.Flags&36)==36,"secret/automap flags preserved");Check(GeometryTools.Far(map,line)>=0&&GeometryTools.Back(map,line)!=null,"portal geometry remains two-sided");Check(blocking!=2||line.Type==52,"dropping monster-only flag permits valid walk-action mapping");Check(converter.Report.Any(s=>s.Contains("Masked middle portal textures omitted"))==masked,"masked omission reported even with general omissions off");Check(converter.Report.Any(s=>s.Contains("monster-only blocking flag dropped"))==((blocking&2)!=0),"monster flag omission reported");
                if(blocking==2&&masked){var target=new Rom(path,resources);target.Project.Maps[0]=map;target.Project.CampaignSlots=new[]{0};byte[] image=target.Compile();string saved=Path.Combine(folder,"open-portal");File.WriteAllBytes(saved+".sfc",image);target.SavePatch(saved+".dse",image);target.SaveProject(saved+".sned");var reopened=new Rom(saved+".sfc",resources);Check(reopened.Project.Maps[0].Walls.Any(w=>GeometryTools.Far(reopened.Project.Maps[0],w)>=0&&(w.Flags&8)==0&&w.Type==52),"open portal and walk exit survive native ROM compilation");}
            }
            string zoo=Path.Combine(Path.GetDirectoryName(path),"zoo.wad");if(File.Exists(zoo)&&Bin.Hex(Bin.Hash(File.ReadAllBytes(zoo)))=="f3f839176ae6a1dc9c52f808dc6d809b79bde3a471065c9462e2ae1693efd691"){var converter=new WadConverter(rom,resources){AllowLossy=true};var map=converter.Import(new WadFile(zoo),"E1M1",0,true);Check(map.Sectors.Count==233,"zoo progresses beyond fence conversion; current merged sector count verified");bool rejected=false;try{rom.Validate(map);}catch(InvalidDataException ex){rejected=ex.Message.Contains("233 / 205 sectors");}Check(rejected,"zoo engine sector limit remains enforced and is explained");File.WriteAllText(Path.Combine(folder,"zoo-analysis.txt"),string.Join("\r\n",converter.Report)+"\r\nStill exceeds the engine sector limit: 233 / 205. General substitutions are needed for unsupported PC objects.\r\n");}
            File.WriteAllText(Path.Combine(output,"portal-020-results.txt"),"PASS monster-only flag removal, explicit impassable preservation, both portal textures omitted by default with strict options, two-sided geometry/automap preservation, walk-action mapping, native build/reimport and zoo sector-limit diagnosis.\r\n");
        }
    }
}

